vector<int> singleNumberIII(vector<int>& nums) {
    long long xor_sum = 0;
    for (int n : nums) xor_sum ^= n;
    long long diff = xor_sum & -xor_sum;
    int a = 0, b = 0;
    for (int n : nums) {
        if (n & diff) a ^= n;
        else b ^= n;
    }
    return {a, b};
}

